package com.retailflow.pos.expense;
import com.retailflow.pos.common.ApiResponse;import java.time.LocalDate;import java.util.stream.Collectors;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/expenses") @PreAuthorize("hasAnyRole('OWNER','MANAGER')") public class ExpenseController{private final ExpenseService s;public ExpenseController(ExpenseService s){this.s=s;}@GetMapping public ApiResponse<?>list(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return ApiResponse.ok(s.list(from,to));}@GetMapping("/{id}")public ApiResponse<?>get(@PathVariable String id){return ApiResponse.ok(s.get(id));}@PostMapping public ApiResponse<?>create(@RequestBody Expense e){return ApiResponse.ok(s.save(e));}@PutMapping("/{id}")public ApiResponse<?>update(@PathVariable String id,@RequestBody Expense e){e.setId(id);return ApiResponse.ok(s.save(e));}@DeleteMapping("/{id}")public ApiResponse<Void>delete(@PathVariable String id){s.delete(id);return ApiResponse.ok(null);}@GetMapping("/summary/category")public ApiResponse<?>category(){return ApiResponse.ok(s.list(null,null).stream().collect(Collectors.groupingBy(Expense::getCategory,Collectors.reducing(java.math.BigDecimal.ZERO,Expense::getAmount,java.math.BigDecimal::add))));}}
